195	        result["plan"] = std::move(plan);
196	    }
197	    // What left the project and what the printers reported, newest first,
198	    // for when the person says how a print went. A print with no finish may
199	    // still be running or may have stopped: nothing records which.
200	    json history = json::array();
201	    for (const AgentRequest::GcodeHistoryEntry& entry : request.gcode_history) {
202	        const GcodeRecord& record = entry.record;
203	        json exports = json::array(), sends = json::array(), prints = json::array();
204	        for (const GcodeDestination& destination : record.destinations) {
205	            if (destination.kind == GcodeDestination::Kind::Export)
206	                exports.push_back(json{{"at", destination.at},
207	                                       {"file", std::filesystem::u8path(destination.path).filename().u8string()}});
208	            else
209	                sends.push_back(json{{"at", destination.at}, {"printer", destination.printer_name},
210	                                     {"startRequested", destination.start_requested}});
211	        }
212	        for (const GcodePrint& print : record.prints) {
213	            json item{{"printer", print.printer_name}, {"startedAt", print.started_at}};
214	            if (!print.finished_at.empty())
215	                item["finishedAt"] = print.finished_at;
216	            prints.push_back(std::move(item));
217	        }
218	        json item{{"gcode", record.hash.substr(0, 8)},
219	                  {"firstLeftAt", record.created_at},
220	                  {"plate", record.plate_name},
221	                  {"printerPreset", record.printer},
222	                  {"filamentPreset", record.material},
223	                  {"processPreset", record.process},
224	                  {"sameInputsAsNow", entry.same_inputs_as_now},
225	                  {"exports", std::move(exports)},
226	                  {"sends", std::move(sends)},
227	                  {"prints", std::move(prints)}};
228	        if (record.statistics.print_time_seconds > 0.0)
229	            item["estimatedSeconds"] = record.statistics.print_time_seconds;
230	        if (record.statistics.material_grams > 0.0)
231	            item["estimatedGrams"] = record.statistics.material_grams;
232	        drop_empty(item);
233	        history.push_back(std::move(item));
234	    }
235	    if (!history.empty())
236	        result["printHistory"] = std::move(history);
237	    return result;
238	}
239	
240	bool available_in_app(const ToolDefinition& definition, bool skills_listed,
241	                      const std::vector<std::string>& session_tools)
242	{
243	    // A session with a subject of its own offers exactly the tools it names,
244	    // and those may be its own rather than the app's.
245	    if (!session_tools.empty())
246	        return std::find(session_tools.begin(), session_tools.end(), definition.name) != session_tools.end() &&
247	               (has_exposure(definition.exposure, ToolExposure::InApp) || has_exposure(definition.exposure, ToolExposure::Printer));
248	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
249	           (definition.availability == ToolAvailability::Always ||
250	            (definition.availability == ToolAvailability::SkillIndex && skills_listed));
251	}
252	
253	// The tools this turn offers, in the registry's order.
254	std::vector<OfferedTool> offered_tools(const AgentRequest& request)
255	{
256	    std::vector<OfferedTool> tools;
257	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
258	        if (!available_in_app(definition, !request.skill_index.empty(), request.session.tool_names))
259	            continue;
260	        // skill_read carries the list it reads from, as one line per skill.
261	        std::string description = definition.description;
262	        if (definition.handler == ToolHandler::SkillRead) {
263	            description += "\n\nSkills:";
264	            for (const AgentSkill& skill : request.skill_index)
265	                description += "\n- " + skill.name + ": " + skill.description;
266	        }
267	        tools.push_back(OfferedTool{&definition, std::move(description)});
268	    }
269	    return tools;
270	}
271	
272	// The skills to send with one request. A skill that yields to another fired
273	// for the same request is left out.
274	std::vector<AgentSkillUse> skills_to_send(const std::vector<AgentSkillUse>& skills)
275	{
276	    std::vector<AgentSkillUse> sent;
277	    for (const AgentSkillUse& skill : skills) {
278	        const bool yields = std::any_of(skills.begin(), skills.end(), [&skill](const AgentSkillUse& other) {
279	            return std::find(skill.yields_to.begin(), skill.yields_to.end(), other.trigger) != skill.yields_to.end();
280	        });
281	        if (!yields)
282	            sent.push_back(skill);
283	    }
284	    return sent;
285	}
