287	AgentHttpHeader auth_header(const ProviderProfile& profile, const std::string& api_key)
288	{
289	    switch (profile.auth) {
290	    case AuthStyle::Bearer: return {"Authorization", "Bearer " + api_key};
291	    case AuthStyle::ApiKeyHeader: return {"x-api-key", api_key};
292	    }
293	    return {"Authorization", "Bearer " + api_key};
294	}
