313	void ProviderAgent::begin_transcript(const AgentRequest& request)
314	{
315	    m_transcript = TurnTranscript{};
316	    m_transcript.request_id   = request.request_id;
317	    m_transcript.chat_key     = request.chat_key;
318	    m_transcript.instructions = request.session.instructions;
319	    m_transcript.opening      = request.conversation;
320	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
321	        return;
322	    m_transcript.tools = offered_tools(request);
323	    m_transcript.opening_once = skills_to_send(request.skills);
324	    // A turn the app started, after one of its own notes: nothing was said,
325	    // and an empty user message would read as the person saying nothing.
326	    if (request.user_text.empty() && request.issue_context.empty() && request.attachments.empty() &&
327	        !request.session.include_workspace)
328	        return;
329	
330	    // One part per kind of content: the person's words exactly as typed, then
331	    // the app's data, each in its own tag, then the attachments.
332	    std::vector<TurnContentPart>& content = m_transcript.user_content;
333	    const auto text = [&content](std::string value) {
334	        TurnContentPart part;
335	        part.text = std::move(value);
336	        content.push_back(std::move(part));
337	    };
338	    if (!request.user_text.empty())
339	        text(request.user_text);
340	    if (!request.issue_context.empty())
341	        text(tagged_block("print_issue", request.issue_context));
342	    if (request.session.include_workspace)
343	        text(tagged_block("workspace", workspace_json(request).dump()));
344	    std::ostringstream attachments;
345	    for (const auto& attachment : request.attachments) {
346	        if (attachments.tellp() > 0)
347	            attachments << "\n";
348	        attachments << "Attachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
349	        if (!attachment.summary.empty())
350	            attachments << " — " << attachment.summary;
351	        if (!attachment.text.empty())
352	            attachments << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
353	    }
354	    if (attachments.tellp() > 0)
355	        text(attachments.str());
356	    for (const auto& attachment : request.attachments) {
357	        if (attachment.bytes.empty())
358	            continue;
359	        TurnContentPart part;
360	        part.mime   = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
361	        part.base64 = base64_encode(attachment.bytes);
362	        if (attachment.kind == "image") {
363	            part.kind = TurnContentPart::Kind::Image;
364	        } else if (attachment.kind == "pdf") {
365	            part.kind     = TurnContentPart::Kind::Pdf;
366	            part.filename = attachment.name;
367	        } else {
368	            continue;
369	        }
370	        content.push_back(std::move(part));
371	    }
372	}
