379	    m_pending_tool.clear();
380	    m_queued_calls.clear();
381	    m_step_skills.clear();
382	    m_failed_call.clear();
383	    m_waiting_for_tool = false;
384	    m_rejected_calls   = 0;
385	    m_paused_turns     = 0;
