391	bool ProviderAgent::continue_after_tool(const AgentToolResult& result)
392	{
393	    if (!m_busy || !m_waiting_for_tool || result.call_id != m_pending_call_id)
394	        return false;
395	    m_transcript.steps.back().results.push_back(
396	        TurnStepResult{result.call_id, result.output_json, result.image, result.state != "succeeded"});
397	    for (const AgentSkillUse& skill : result.skills) {
398	        const auto same = std::find_if(m_step_skills.begin(), m_step_skills.end(),
399	                                       [&skill](const AgentSkillUse& pending) { return pending.name == skill.name; });
400	        if (same != m_step_skills.end())
401	            *same = skill;
402	        else
403	            m_step_skills.push_back(skill);
404	    }
405	    if (result.state != "succeeded" && m_failed_call.empty())
406	        m_failed_call = m_pending_tool + " (" + m_pending_call_id + ")";
407	    m_waiting_for_tool = false;
408	    m_pending_call_id.clear();
409	    m_pending_tool.clear();
410	    return next_call();
411	}
