418	bool ProviderAgent::post()
419	{
420	    m_sse_buffer.clear();
421	    m_terminal_seen = false;
422	    m_busy = true;
423	    ++m_transcript.request_sequence;
424	    m_codec->reset();
425	    ProviderRequest built = m_codec->build(m_transcript, m_config.profile, m_kind);
426	    AgentHttpRequest request;
427	    request.url = m_config.profile.endpoint;
428	    request.headers.push_back(auth_header(m_config.profile, m_config.api_key));
429	    request.headers.insert(request.headers.end(), m_config.profile.headers.begin(), m_config.profile.headers.end());
430	    request.headers.insert(request.headers.end(), built.headers.begin(), built.headers.end());
431	    if (m_config.profile.account_sign_in) {
432	        request.headers.push_back({"X-JusPrin-Turn", m_transcript.request_id});
433	        request.headers.push_back({"X-JusPrin-Request", m_kind == RequestKind::ConversationTitle ? "title" : "reply"});
434	    }
435	    request.body = built.body.dump();
436	    const std::uint64_t generation = ++m_http_generation;
437	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
438	            accept_http(generation, std::move(event));
439	        })) {
440	        m_busy = false;
441	        return false;
442	    }
443	    return true;
444	}
