446	void ProviderAgent::accept_http(std::uint64_t generation, AgentHttpEvent event)
447	{
448	    std::lock_guard<std::mutex> lock(m_mutex);
449	    m_http_events.push_back(QueuedHttpEvent{generation, std::move(event)});
450	}
