452	void ProviderAgent::parse_sse_frame(const std::string& frame)
453	{
454	    std::string payload;
455	    std::istringstream lines(frame);
456	    std::string line;
457	    while (std::getline(lines, line)) {
458	        if (!line.empty() && line.back() == '\r')
459	            line.pop_back();
460	        if (line.rfind("data:", 0) == 0) {
461	            std::string part = line.substr(5);
462	            if (!part.empty() && part.front() == ' ')
463	                part.erase(part.begin());
464	            if (!payload.empty())
465	                payload += '\n';
466	            payload += part;
467	        }
468	    }
469	    if (payload.empty() || payload == "[DONE]")
470	        return;
471	    for (StreamEvent& event : m_codec->parse(payload))
472	        handle(std::move(event));
473	}
474	
475	void ProviderAgent::handle(StreamEvent event)
476	{
477	    switch (event.kind) {
478	    case StreamEvent::Kind::TextDelta: m_events.push_back(AgentEvent::delta(std::move(event.text))); break;
479	    case StreamEvent::Kind::TurnComplete: finish_response(std::move(event)); break;
480	    case StreamEvent::Kind::Incomplete:
481	        fail(AgentError{"incomplete_response", "The Agent service stopped before finishing its response.", true});
482	        break;
483	    case StreamEvent::Kind::Failed: fail(std::move(event.error)); break;
484	    }
485	}
486	
487	void ProviderAgent::finish_response(StreamEvent event)
488	{
489	    if (m_terminal_seen)
490	        return;
491	    m_terminal_seen = true;
492	    if (m_config.usage_listener && event.usage)
493	        m_config.usage_listener(*event.usage);
494	    m_queued_calls.clear();
495	    m_step_skills.clear();
496	    m_failed_call.clear();
497	    m_transcript.steps.push_back(TurnStep{std::move(event.assistant_turn), {}, {}});
498	    if (event.resend) {
499	        // The provider paused its own turn and resumes it from this one.
500	        constexpr unsigned kPausedTurnLimit = 4;
501	        if (++m_paused_turns > kPausedTurnLimit) {
502	            fail(AgentError{"agent_paused_too_often", "The Agent service kept pausing its response.", true});
503	            return;
504	        }
505	        if (!post())
506	            fail(AgentError{"agent_continuation_failed", "The Agent could not be asked to continue its response.", true});
507	        return;
508	    }
509	    for (ProviderToolCall& call : event.calls)
510	        m_queued_calls.push_back(std::move(call));
511	    if (!next_call())
512	        fail(AgentError{"agent_continuation_failed", "The Agent could not be told the results of its tool calls.", true});
513	}
514	
515	// Hands out the next call of the response, or, once every call has its
516	// result, sends them all back. Whatever the model sent, the next request
517	// never carries a call without its result. False only when that request
518	// could not be sent.
519	bool ProviderAgent::next_call()
520	{
521	    while (!m_queued_calls.empty()) {
522	        const ProviderToolCall item = std::move(m_queued_calls.front());
523	        m_queued_calls.pop_front();
524	        const std::string& call_id = item.call_id;
525	        ToolRequest request{item.name, item.arguments_json};
526	        // The model chose this call before it saw the earlier call fail, so
527	        // it is answered unrun and the model decides again with both results.
528	        if (!call_id.empty() && !m_failed_call.empty()) {
529	            answer_call(call_id, json{{"state", "failed"},
530	                                      {"error", json{{"code", "not_run"},
531	                                                     {"message", "Not run: an earlier call in the same response, " + m_failed_call +
532	                                                                     ", did not succeed. Nothing was queued. Call it again if it is "
533	                                                                     "still needed."}}}});
534	            continue;
535	        }
536	        const auto offered = std::find_if(m_transcript.tools.begin(), m_transcript.tools.end(),
537	                                          [&request](const OfferedTool& tool) { return tool.definition->name == request.tool; });
538	        const bool available = m_kind == RequestKind::Reply && offered != m_transcript.tools.end();
539	        ToolValidationResult validation;
540	        if (available)
541	            validation = ToolRegistry::instance().validate_call(*offered->definition, request.arguments_json);
542	        // A call to no tool of this turn, or with arguments that miss the
543	        // tool's contract, never reaches a card. The model gets the refusal as
544	        // that call's result and may correct it, a bounded number of times
545	        // per turn.
546	        constexpr unsigned kRejectedCallLimit = 2;
547	        if ((!available || !validation.valid()) && m_config.refusal_listener)
548	            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
549	        if (!call_id.empty() && m_kind == RequestKind::Reply && (!available || !validation.valid()) &&
550	            m_rejected_calls < kRejectedCallLimit) {
551	            ++m_rejected_calls;
552	            json error = available ?
553	                json{{"code", validation.error->code},
554	                     {"message", validation.error->message +
555	                                     " Nothing was queued. Check the arguments against this tool's parameters and call it again."}} :
556	                json{{"code", "unknown_tool"},
557	                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. Use one of the listed tools."}};
558	            answer_call(call_id, json{{"state", "failed"}, {"error", std::move(error)}});
559	            m_failed_call = request.tool + " (" + call_id + ")";
560	            continue;
561	        }
562	        if (call_id.empty() || !available || !validation.valid()) {
563	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
564	            return true;
565	        }
566	        request.arguments_json = std::move(validation.arguments_json);
567	        m_pending_call_id = call_id;
568	        m_pending_tool    = request.tool;
569	        m_waiting_for_tool = true;
570	        AgentToolCall call{call_id, std::move(request), true};
571	        m_events.push_back(AgentEvent::tool_call(std::move(call)));
572	        return true;
573	    }
574	    if (m_transcript.steps.back().results.empty()) {
575	        m_busy = false;
576	        m_events.push_back(AgentEvent::completed());
577	        return true;
578	    }
579	    m_transcript.steps.back().once = skills_to_send(m_step_skills);
580	    m_step_skills.clear();
581	    return post();
582	}
