584	void ProviderAgent::parse_available()
585	{
586	    std::deque<QueuedHttpEvent> incoming;
587	    {
588	        std::lock_guard<std::mutex> lock(m_mutex);
589	        incoming.swap(m_http_events);
590	    }
591	    for (QueuedHttpEvent& queued : incoming) {
592	        if (queued.generation != m_http_generation)
593	            continue;
594	        AgentHttpEvent& event = queued.event;
595	        if (event.kind == AgentHttpEvent::Kind::Data) {
596	            m_sse_buffer += event.data;
597	            for (;;) {
598	                const std::size_t lf_pos = m_sse_buffer.find("\n\n");
599	                const std::size_t crlf_pos = m_sse_buffer.find("\r\n\r\n");
600	                const bool crlf_first = crlf_pos != std::string::npos &&
601	                                        (lf_pos == std::string::npos || crlf_pos < lf_pos);
602	                const std::size_t pos = crlf_first ? crlf_pos : lf_pos;
603	                if (pos == std::string::npos)
604	                    break;
605	                const std::string frame = m_sse_buffer.substr(0, pos);
606	                m_sse_buffer.erase(0, pos + (crlf_first ? 4 : 2));
607	                parse_sse_frame(frame);
608	            }
609	        } else if (event.kind == AgentHttpEvent::Kind::Error) {
610	            fail(http_error(event.status, event.error));
611	        } else if (!m_terminal_seen) {
612	            // A valid SSE stream may close immediately after its final data
613	            // line without a trailing blank-line delimiter. Consume that
614	            // complete residual frame before classifying the response.
615	            if (!m_sse_buffer.empty()) {
616	                parse_sse_frame(m_sse_buffer);
617	                m_sse_buffer.clear();
618	            }
619	            if (!m_terminal_seen)
620	                fail(AgentError{"malformed_response", "The Agent service ended before a complete response arrived.", true});
621	        }
622	    }
623	}
624	
625	std::optional<AgentEvent> ProviderAgent::poll()
626	{
627	    parse_available();
628	    if (m_events.empty())
629	        return std::nullopt;
630	    AgentEvent event = std::move(m_events.front());
631	    m_events.pop_front();
632	    return event;
633	}
634	
635	AgentError ProviderAgent::http_error(unsigned status, const std::string& detail) const
636	{
637	    const std::string& name = m_config.profile.display_name;
638	    if (m_config.profile.account_sign_in && (status == 401 || status == 403))
639	        return {"invalid_credentials", "Your JusPrin sign-in has ended. Sign in again in Preferences, then try again.", false};
640	    if (m_config.profile.account_sign_in && status == 402)
641	        return {"quota_exhausted", "Your JusPrin account has used its Agent allowance for now. See your account for more.", false};
642	    if (status == 401 || status == 403)
643	        return {"invalid_credentials", "The " + name + " API key was rejected. Update the Agent configuration and try again.", false};
644	    if (status == 413)
645	        return {"request_too_large", "The request was too large for the " + name + " service.", false};
646	    if (status == 429)
647	        return {"rate_limited", "The " + name + " service is rate limited. Try again shortly.", true};
648	    if (status == 529)
649	        return {"service_overloaded", "The " + name + " service is overloaded. Try again shortly.", true};
650	    if (status >= 500)
651	        return {"service_unavailable", "The " + name + " service is temporarily unavailable.", true};
652	    if (status == 408 || detail.find("timed out") != std::string::npos || detail.find("Timeout") != std::string::npos)
653	        return {"timeout", "The Agent request timed out.", true};
654	    return {"network_error", "The Agent request could not reach the " + name + " service.", true};
655	}
656	
657	void ProviderAgent::fail(AgentError error)
658	{
659	    if (!m_busy && m_terminal_seen)
660	        return;
661	    m_busy = false;
662	    m_waiting_for_tool = false;
663	    m_queued_calls.clear();
664	    m_terminal_seen = true;
665	    m_events.push_back(AgentEvent::failed(std::move(error)));
666	}
