668	void ProviderAgent::cancel()
669	{
670	    if (m_transport)
671	        m_transport->cancel();
672	    ++m_http_generation;
673	    {
674	        std::lock_guard<std::mutex> lock(m_mutex);
675	        m_http_events.clear();
676	    }
677	    m_events.clear();
678	    m_sse_buffer.clear();
679	    m_queued_calls.clear();
680	    m_busy = false;
681	    m_waiting_for_tool = false;
682	    m_terminal_seen = true;
683	}
