// One part of an item on the person's side of a chat's record: text, or a
// picture or PDF whose bytes live in a blob beside the document, never in it.
struct RecordPart
{
    enum class Kind { Text, Image, Pdf };
    Kind        kind{Kind::Text};
    std::string text;     // Text
    std::string mime;     // Image, Pdf
    std::string filename; // Pdf
    // Image, Pdf: the blob's path relative to the JusPrin data dir, set when
    // the item is recorded.
    std::string blob;
    // Image, Pdf: the bytes as sent, in memory only.
    std::string base64;
};

// A call's result, as the model was told it.
struct RecordResult
{
    std::string               call_id;
    std::string               output_json;
    bool                      failed{false}; // failed, cancelled, refused or not run
    std::optional<RecordPart> image;
};

// One item of a chat's record: something the model was sent, kept as sent so
// every later request repeats it unchanged. Who speaks decides the kind:
// the person's side (their words and the app's data that travels with them:
// workspace block, file report, pictures), the operator (app notes and fired
// skills), the model (its output, thinking included, verbatim), and tool
// results, which stay in their own channel.
struct RecordItem
{
    enum class Kind { User, Operator, Assistant, Results };
    Kind                      kind{Kind::User};
    // The chat message the item came from, when it came from one.
    std::string               source;
    std::vector<RecordPart>   parts;   // User
    // Operator: its text. Assistant: a reply recorded before the record
    // existed, as plain text, where `output` is null.
    std::string               text;
    // Operator: visible only on the request that first carried it; the
    // provider stops rendering it at the next user-role message (Anthropic's
    // clear_at). Decided when it is first sent and never changed.
    bool                      clears{false};
    nlohmann::json            output;  // Assistant: the provider's own output
    std::vector<RecordResult> results; // Results
};

// Everything one chat has sent to the model, in order, in one wire format
// ("anthropic" or "responses"; empty until the first item from a provider).
// Items are only ever appended.
struct ChatRecord
{
    std::string             format;
    std::vector<RecordItem> items;
    // Messages the record holds, or that the migration of an older chat
    // left out on purpose: none of them is sent again.
    std::vector<std::string> messages;
};

struct ConversationInfo
{

bool                           set_chat_model(const std::string& conversation_id, const ChatModelChoice& choice);
// What the chat has sent to the model. Absent for a chat that has sent
// nothing since the record was introduced. Picture bytes are not loaded.
std::optional<ChatRecord> chat_record(const std::string& conversation_id) const;
// Appends items as sent, in `format`. A format other than the record's,
// or a picture without its blob, is a logic error.
void append_chat_record(const std::string& conversation_id, const std::string& format,
                        const std::vector<RecordItem>& items);
// Starts the record of a chat that talked before records existed: its
// earlier exchange as plain text, and every message it covers. Once.
void start_chat_record(const std::string& conversation_id, const std::vector<RecordItem>& items,
                       const std::vector<std::string>& messages);

    std::vector<std::string> messages;
};

// Where a chat's record keeps the bytes of the pictures and PDFs it sent,
// relative to the JusPrin data dir, beside the attachment blobs.
inline std::string chat_record_dir(const std::string& conversation_id) { return "attachments/chat-" + conversation_id; }

json record_part_json(const RecordPart& part)
{
    if (part.kind == RecordPart::Kind::Text)
        return json{{"text", part.text}};
    if (part.blob.empty())
        throw std::logic_error("a recorded picture or PDF has no blob");
    json entry{{part.kind == RecordPart::Kind::Image ? "image" : "pdf", part.blob}, {"mime", part.mime}};
    if (!part.filename.empty())
        entry["filename"] = part.filename;
    return entry;
}

RecordPart record_part_from(const json& entry)
{
    RecordPart part;
    if (entry.contains("text")) {
        part.text = entry["text"].get<std::string>();
        return part;
    }
    part.kind     = entry.contains("image") ? RecordPart::Kind::Image : RecordPart::Kind::Pdf;
    part.blob     = entry.value(entry.contains("image") ? "image" : "pdf", "");
    part.mime     = entry.value("mime", "");
    part.filename = entry.value("filename", "");
    return part;
}

const char* record_kind_name(RecordItem::Kind kind)
{
    switch (kind) {
    case RecordItem::Kind::User: return "user";
    case RecordItem::Kind::Operator: return "operator";
    case RecordItem::Kind::Assistant: return "assistant";
    case RecordItem::Kind::Results: return "results";
    }
    return "user";
}

json record_item_json(const RecordItem& item)
{
    json entry{{"kind", record_kind_name(item.kind)}};
    if (!item.source.empty())
        entry["source"] = item.source;
    switch (item.kind) {
    case RecordItem::Kind::User:
        entry["parts"] = json::array();
        for (const RecordPart& part : item.parts)
            entry["parts"].push_back(record_part_json(part));
        break;
    case RecordItem::Kind::Operator:
        entry["text"] = item.text;
        if (item.clears)
            entry["clears"] = true;
        break;
    case RecordItem::Kind::Assistant:
        if (item.output.is_null())
            entry["text"] = item.text;
        else
            entry["output"] = item.output;
        break;
    case RecordItem::Kind::Results:
        entry["results"] = json::array();
        for (const RecordResult& result : item.results) {
            json stored{{"callId", result.call_id}, {"output", result.output_json}};
            if (result.failed)
                stored["failed"] = true;
            if (result.image)
                stored["image"] = record_part_json(*result.image);
            entry["results"].push_back(std::move(stored));
        }
        break;
    }
    return entry;
}

RecordItem record_item_from(const json& entry)
{
    RecordItem  item;
    const std::string kind = entry.at("kind").get<std::string>();
    item.source = entry.value("source", "");
    if (kind == "user") {
        item.kind = RecordItem::Kind::User;
        for (const json& part : entry.at("parts"))
            item.parts.push_back(record_part_from(part));
    } else if (kind == "operator") {
        item.kind   = RecordItem::Kind::Operator;
        item.text   = entry.at("text").get<std::string>();
        item.clears = entry.value("clears", false);
    } else if (kind == "assistant") {
        item.kind   = RecordItem::Kind::Assistant;
        item.output = entry.value("output", json());
        item.text   = entry.value("text", "");
    } else if (kind == "results") {
        item.kind = RecordItem::Kind::Results;
        for (const json& stored : entry.at("results")) {
            RecordResult result{stored.at("callId").get<std::string>(), stored.at("output").get<std::string>(),
                                stored.value("failed", false), std::nullopt};
            if (stored.contains("image"))
                result.image = record_part_from(stored["image"]);
            item.results.push_back(std::move(result));
        }
    } else {
        throw std::invalid_argument("Unknown chat record item kind: " + kind);
    }
    return item;
}

// Updates the known fields of an existing JSON object in place, so fields
// written by other builds are preserved.

std::optional<ChatRecord> ProjectStateDocument::chat_record(const std::string& conversation_id) const
{
    const json* conversation = conversation_json(conversation_id);
    if (!conversation || !conversation->contains("record"))
        return std::nullopt;
    const json& stored = (*conversation)["record"];
    ChatRecord  record;
    record.format   = stored.value("format", "");
    record.messages = stored.value("messages", std::vector<std::string>{});
    for (const json& entry : stored.at("items"))
        record.items.push_back(record_item_from(entry));
    return record;
}

void ProjectStateDocument::append_chat_record(const std::string& conversation_id, const std::string& format,
                                              const std::vector<RecordItem>& items)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation)
        throw std::logic_error("a record for a chat the document does not hold");
    json& stored = (*conversation)["record"];
    if (stored.is_null())
        stored = json{{"format", ""}, {"items", json::array()}, {"messages", json::array()}};
    if (stored["format"] == "")
        stored["format"] = format;
    else if (stored["format"] != format)
        throw std::logic_error("a chat recorded in " + stored["format"].get<std::string>() + " cannot take items in " + format);
    for (const RecordItem& item : items) {
        stored["items"].push_back(record_item_json(item));
        if (!item.source.empty())
            stored["messages"].push_back(item.source);
    }
    touch();
}

void ProjectStateDocument::start_chat_record(const std::string& conversation_id, const std::vector<RecordItem>& items,
                                             const std::vector<std::string>& messages)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation || conversation->contains("record"))
        throw std::logic_error("a chat record can be started once, for a chat the document holds");
    json entries = json::array();
    for (const RecordItem& item : items)
        entries.push_back(record_item_json(item));
    (*conversation)["record"] = json{{"format", ""}, {"items", std::move(entries)}, {"messages", messages}};
    touch();
}

