new='''// Answers each turn with text, or with the one tool call it was given, and
// records every request and tool result the host hands it. It keeps what it
// sent in the chat's record the way a provider agent does: the person's side
// once sent, then each reply and result, so a later request carries them.
class ScriptedAgent final : public Agent::IAgentService
{
public:
    std::optional<Agent::ToolRequest>   call;
    std::string                         reply{"Understood."};
    std::vector<Agent::AgentRequest>    requests;
    std::vector<Agent::AgentToolResult> results;

    bool ready() const override { return true; }
    bool busy() const override { return m_active; }
    bool start(const Agent::AgentRequest& request) override
    {
        requests.push_back(request);
        m_active = true;
        m_record = request.on_recorded;
        if (request.purpose == Agent::AgentRequest::Purpose::ConversationTitle) {
            m_events.push_back(Agent::AgentEvent::delta("Printer"));
            m_events.push_back(Agent::AgentEvent::completed());
            return true;
        }
        std::vector<Agent::RecordItem> sent;
        for (const Agent::AgentUnsentMessage& message : request.unsent)
            sent.push_back(message.note ? Agent::RecordItem{Agent::RecordItem::Kind::Operator, message.id, {}, message.text}
                                        : Agent::RecordItem{Agent::RecordItem::Kind::User, message.id, {text(message.text)}});
        if (!request.source.empty() || !request.user_text.empty())
            sent.push_back({Agent::RecordItem::Kind::User, request.source, {text(request.user_text)}});
        if (call) {
            m_call_id = "call-" + std::to_string(requests.size());
            sent.push_back({Agent::RecordItem::Kind::Assistant, {}, {}, {},
                            json{{"type", "function_call"}, {"call_id", m_call_id}, {"name", call->tool}, {"arguments", call->arguments_json}}});
            m_events.push_back(Agent::AgentEvent::tool_call({m_call_id, *call, true}));
            call.reset();
        } else {
            sent.push_back(said(reply));
            m_events.push_back(Agent::AgentEvent::delta(reply));
            m_events.push_back(Agent::AgentEvent::completed());
        }
        keep(std::move(sent));
        return true;
    }
    bool continue_after_tool(const Agent::AgentToolResult& result) override
    {
        results.push_back(result);
        Agent::RecordItem answered{Agent::RecordItem::Kind::Results};
        answered.results.push_back({result.call_id, result.output_json, result.state != "succeeded"});
        keep({std::move(answered), said("Done.")});
        m_events.push_back(Agent::AgentEvent::delta("Done."));
        m_events.push_back(Agent::AgentEvent::completed());
        return true;
    }
    void cancel() override
    {
        m_active = false;
        m_events.clear();
    }
    std::optional<Agent::AgentEvent> poll() override
    {
        if (m_events.empty())
            return std::nullopt;
        Agent::AgentEvent event = std::move(m_events.front());
        m_events.pop_front();
        if (event.kind == Agent::AgentEventKind::Completed || event.kind == Agent::AgentEventKind::Failed)
            m_active = false;
        return event;
    }

private:
    static Agent::RecordPart text(const std::string& words) { return {Agent::RecordPart::Kind::Text, words}; }
    static Agent::RecordItem said(const std::string& words)
    {
        return {Agent::RecordItem::Kind::Assistant, {}, {}, {}, json{{"type", "message"}, {"role", "assistant"}, {"content", words}}};
    }
    void keep(std::vector<Agent::RecordItem> items)
    {
        if (m_record)
            m_record("responses", std::move(items));
    }

    std::deque<Agent::AgentEvent> m_events;
    std::function<void(const std::string&, std::vector<Agent::RecordItem>)> m_record;
    std::string                   m_call_id;
    bool                          m_active{false};
};

