std::optional<ChatRecord> ProjectStateDocument::chat_record(const std::string& conversation_id) const
{
    const json* conversation = conversation_json(conversation_id);
    if (!conversation || !conversation->contains("record"))
        return std::nullopt;
    const json& stored = (*conversation)["record"];
    ChatRecord  record;
    record.format   = stored.value("format", "");
    record.messages = stored.value("messages", std::vector<std::string>{});
    for (const json& entry : stored.at("items"))
        record.items.push_back(record_item_from(entry));
    return record;
}

void ProjectStateDocument::append_chat_record(const std::string& conversation_id, const std::string& format,
                                              const std::vector<RecordItem>& items)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation)
        throw std::logic_error("a record for a chat the document does not hold");
    json& stored = (*conversation)["record"];
    if (stored.is_null())
        stored = json{{"format", ""}, {"items", json::array()}, {"messages", json::array()}};
    if (stored["format"] == "")
        stored["format"] = format;
    else if (stored["format"] != format)
        throw std::logic_error("a chat recorded in " + stored["format"].get<std::string>() + " cannot take items in " + format);
    for (const RecordItem& item : items) {
        stored["items"].push_back(record_item_json(item));
        if (!item.source.empty())
            stored["messages"].push_back(item.source);
    }
    touch();
}

void ProjectStateDocument::start_chat_record(const std::string& conversation_id, const std::vector<RecordItem>& items,
                                             const std::vector<std::string>& messages)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation || conversation->contains("record"))
        throw std::logic_error("a chat record can be started once, for a chat the document holds");
    json entries = json::array();
    for (const RecordItem& item : items)
        entries.push_back(record_item_json(item));
    (*conversation)["record"] = json{{"format", ""}, {"items", std::move(entries)}, {"messages", messages}};
    touch();
}

